func (s *Store) upsertSubmissionsTx(tx *sql.Tx, data json.RawMessage) error {
	var obj map[string]any
	if err := json.Unmarshal(data, &obj); err != nil {
		return fmt.Errorf("unmarshaling submissions: %w", err)
	}
	id := extractObjectID(obj)
	if id == "" {
		return fmt.Errorf("missing id for submissions")
	}
	if err := s.upsertGenericResourceTx(tx, "submissions", id, data); err != nil {
		return err
	}
	_, err := tx.Exec(
		`INSERT INTO submissions (id, bounties_id, data, synced_at)
		 VALUES (?, ?, ?, ?)
		 ON CONFLICT(id) DO UPDATE SET bounties_id = excluded.bounties_id, data = excluded.data, synced_at = excluded.synced_at`,
		id, stringValue(lookupFieldValue(obj, "bounties_id")), string(data), time.Now(),
	)
	return err
}

