// UpsertBatch inserts or replaces multiple records in a single transaction.
// This is 10-100x faster than individual Upsert calls for bulk operations.
func (s *Store) UpsertBatch(resourceType string, items []json.RawMessage) error {
	return s.withTx(func(tx *sql.Tx) error {
		for _, item := range items {
			var obj map[string]any
			if err := json.Unmarshal(item, &obj); err != nil {
				continue
			}
			id := fmt.Sprintf("%v", lookupFieldValue(obj, "id"))
			if id == "" || id == "<nil>" {
				continue
			}
			var err error
			switch resourceType {
			case "links":
				err = s.upsertLinkTx(tx, item)
			case "events":
				err = s.upsertEventTx(tx, item)
			case "submissions":
				err = s.upsertSubmissionsTx(tx, item)
			default:
				err = s.upsertGenericResourceTx(tx, resourceType, id, item)
			}
			if err != nil {
				return fmt.Errorf("upserting %s/%s: %w", resourceType, id, err)
			}
		}
		return nil
	})
}

func (s *Store) searchFTS(table, fts, query string, limit int) ([]json.RawMessage, error) {
	if limit <= 0 {
		limit = 50
	}
	rows, err := s.db.Query(fmt.Sprintf(`SELECT t.data FROM %s t JOIN %s ON %s.rowid = t.rowid WHERE %s MATCH ? ORDER BY rank LIMIT ?`, table, fts, fts, fts), query, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var results []json.RawMessage
	for rows.Next() {
		var data string
		if err := rows.Scan(&data); err != nil {
			return nil, err
		}
		results = append(results, json.RawMessage(data))
	}
	return results, rows.Err()
}

